def build():
    DOCS.mkdir(parents=True,exist_ok=True)
    with (ROOT/"reference/metrics_catalog.csv").open(encoding="utf-8-sig") as stream:catalog=list(csv.DictReader(stream))
    passports=(ROOT/"reference/da_metrics.md").read_text()
    blocks={m.group(1):m.group(2) for m in re.finditer(r"^### ([FGE]-\d+)\.[^\n]*\n(.*?)(?=^### |\Z)",passports,re.M|re.S)}
    lines=["# Как объяснять расчёты DA", "", "Источник: закреплённый каталог и паспорта в `reference/`; ревизии перечислены в `reference/snapshot.json`. Все числа считает код DA, PE формулирует объяснение.", "", "## Метрики", "", "Покрыты все 54 P0-метрики каталога и остальные признаки F/G/E. Остальные группы приведены в P0-объёме. Вход в промпт всегда включает готовое значение, единицу, дату и ID доказательства; пропуск остаётся NULL.", "", "| ID и название | Что это | Как сказать пользователю | Как использовать | Чего нельзя утверждать |", "|---|---|---|---|---|---|"]
    covered=[]
    for row in catalog:
        mid=row["id"]
        if row["приоритет"]!="P0" and row["группа"] not in {"F","G","E"}:continue
        covered.append(mid)
        block=blocks.get(mid,"")
        fields={m.group(1).strip():m.group(2).strip() for m in re.finditer(r"^\| ([^|]+) \| (.+) \|$",block,re.M)}
        phrase,forbidden=EXPLANATIONS.get(mid,(fields.get("Как объяснять пользователю",row["название"]),fields.get("Чего нельзя утверждать","Не выходить за готовые расчёты и видимые данные")))
        usage=fields.get("Использование",f"Передать {mid} как готовое значение с единицей {row['единицы']} и source_ids")
        lines.append("| "+" | ".join(clean(x) for x in (mid+" "+row["название"],row["определение / формула"],phrase,usage,forbidden))+" |")
    lines += ["", "## Формулы FM-01..FM-24", "", "Для FM-06 и FM-22 в документах есть расхождения с реализацией. На границе PE передаётся готовый результат и версия расчёта; PE не выбирает другую формулу. Спорные формулы нужно подтвердить у DA/BA.", "", "| ID | Что это | Как объяснять / использовать | Ограничение |", "|---|---|---|---|"]
    for n,(name,phrase,limit) in FORMULAS.items():lines.append(f"| FM-{n} | {name} | {phrase}; передавать результат как COMPUTED_VALUE с входными ID | {limit} |")
    lines += ["", "## Обязательные графики", "", "| ID | Как читать и объяснять | Что подписать | Ограничение |", "|---|---|---|---|",
        "| CH-06 | Радар показывает различия чувствительности по 12 осям | Клиенты, диапазон, источник и дата | Не смешивать величину чувствительности и знак эффекта |",
        "| CH-07 | Матрица отраслевых prior, значения 0..3 | Отрасли, факторы, шкала | Это справочная гипотеза, не измерение договоров клиента |",
        "| CH-08 | Факт ставки отдельно от прогноза банка | Легенда факт/прогноз, дата версии и горизонт | DA ждёт ряды M/B; при отсутствии рядов не рисовать историю из памяти |",
        "| CH-14 | Готовые вклады в итоговый скор | Факторы, веса и общий скор | Не суммировать и не менять значения в LLM |",
        "| CH-15 | Пересечение лент показывает различия отбора | Размер топа, пары клиентов, PD@5 | В DA это макет до реального контура |",
        "| CH-23 | Распределение релевантности по отраслям | Объём выборки, порог и единицы | Макет нельзя выдавать за фактическую калибровку |",
        "| CH-25 | Воронка показывает потери на этапах отбора | Число событий на каждой стадии | Показатели макета заменяются логами настоящего запуска |",
        "", "## Глоссарий и тон", "", "ЛПР — руководитель, принимающий решение; ДКП — денежно-кредитная политика; ОФЗ — облигации федерального займа; п.п. — разность процентных ставок; г/г — сравнение с тем же периодом прошлого года; м/м — с прошлым месяцем; н/н — с прошлой неделей; ВЭД — внешнеэкономическая деятельность; экспозиция — чувствительность к фактору; prior — исходная отраслевая гипотеза; NULL — данных нет; MMR — отбор с ограничением повторов.", "", "Тон: короткие деловые предложения; сначала наблюдение, затем механизм и связь с компанией. Действия — вопросы для проверки и варианты обсуждения. Прогноз сопровождается датой и горизонтом. Каждая карточка содержит оговорку «Не является индивидуальной инвестиционной рекомендацией».", ""]
    (DOCS/"02_da_processing_explained.md").write_text("\n".join(lines))
    manifest=json.loads((ROOT/"prompts/manifest.json").read_text())
    model_lines=["# Какие модели и для каких данных", "", "Список и точные API ID: `config/organiser_models.json`. Секрет находится только в `.env`; общий лимит ключа — 500 ₽/сутки, рабочая цель — 400 ₽. Генератор и критик/судья используют разные семейства.", "", "| Задача / данные | Промпты | Стартовая модель | Запасной кандидат | Выход / лимит |", "|---|---|---|---|---|"]
    role_info=[("Новость: тип, сущности, факты и вектор","01,02","Gemma 4 26B A4B","Qwen3.6 35B A3B","EventExtraction / ImpactVector; 4096"),
        ("Изображение страницы PDF","03","Qwen3-VL-30B-A3B-Instruct","Нет другой VLM в списке","Chunk; 4096, при исправлении до 8192"),
        ("Фрагменты банковских отчётов","04","Gemma 4 26B A4B","Qwen3.6 35B A3B","BankViewExtraction; 4096"),
        ("Событие и рассчитанные признаки клиента","05,06,09,10,17","GLM-5.3-Flash","DeepSeek-V4.1-Flash","EventCore / PersonalOverlay / explanation; 4096"),
        ("Карточка и её доказательства","07","Qwen3.6 35B A3B","Kimi-K2.6","CriticVerdict; 6144"),
        ("Вопрос, сценарий, график, версия, уверенность, предложение","08,11,12,13,14,15","Qwen3.6 35B A3B","GLM-5.3-Flash при независимой критике","ChatAnswer / explanation / offer; 4096"),
        ("Офлайн-рубрика Q-08 и длинный контекст","16","Kimi-K2.6","DeepSeek-V4.1-Flash при генераторе GLM","JudgeScore; 4096"),
        ("Ранжирование, фильтры и расчёты","Без LLM","Код DA","Без LLM","FM-xx / 0 токенов")]
    for row in role_info:model_lines.append("| "+" | ".join(row)+" |")
    model_lines += ["", "## Замеры и правило выбора", "", "Интерпретация сравнивается на 12 seed-случаях между GLM и DeepSeek. Критик — между Qwen и Kimi. Судья другого семейства оценивает Q-08; итоговое принятие требует также эксперта. Минимальная стоимость выбирается только среди кандидатов, прошедших пороги качества. Если рублёвые тарифы неизвестны, лидер по цене не назначается.", "", "Результаты: [отчёт приёмки](evaluation/acceptance_summary.md). Прогон структурированного аудита GLM на 1000 случаях показал 999/1000 и Audit Score 0.997; это отдельная задача, не замер качества генератора или PRM-07.", "", "Политика: температура 0; GLM получает reasoning_effort=low, поскольку общий бюджет вывода включает рассуждения. Вызовы ограничены PromptSession, JSON исправляется не более одного раза, у карточки не более одного общего цикла исправления. VLM работает по страницам с кэшем; общее ядро события не включает профиль клиента и пригодно для повторного использования.", "", "Токены по операциям сохраняются в `prompts/token_budget.csv`. Рублёвая стоимость карточки: сумма `(tokens_in*p_in + tokens_out*p_out)` по операциям с учётом кэша. Суточная ёмкость — `floor(400/cost_card)`. Без подтверждённых p_in/p_out оба значения остаются неизвестными; серверный hard cap 500 ₽ не доказывает соблюдение цели 400 ₽.", ""]
    results=DOCS/'evaluation/acceptance_results.json'
    if results.exists():
        measured=json.loads(results.read_text())
        model_lines+=['## Фактические замеры кандидатов','',
            '| Генератор | Принято карточек | Q-01, proxy | Q-03, proxy | Q-08, модель | p50 вызова генерации, с | Стоимость, ₽ |',
            '|---|---|---|---|---|---|---|']
        for model,item in measured['generators'].items():
            fmt=lambda value:'не измерено' if value is None else str(round(value,3))
            latency=item.get('generation_call_latency_p50_ms')
            model_lines.append(f"| {model} | {item['cards_accepted']}/{item['cards_tested']} | {fmt(item['faithfulness_critic_proxy'])} | {fmt(item['fact_error_critic_proxy'])} | {fmt(item['q08_model_judge'])} | {fmt(latency/1000 if latency is not None else None)} | неизвестна |")
        model_lines+=['','| Критик | Найдено ошибок | p50 вызова, с | Стоимость, ₽ |','|---|---|---|---|']
        for model,item in measured['critics'].items():
            latency=item.get('critic_call_latency_p50_ms')
            model_lines.append(f"| {model} | {item['defects_found']}/{item['defects_tested']} | {round(latency/1000,3) if latency is not None else 'не измерено'} | неизвестна |")
        model_lines+=['','p50 рассчитана по сохранённым некэшированным вызовам соответствующей операции, включая исправления, а не по полной задержке карточки. Q-01/Q-03 — оценки критика, используемого в проверке; Q-08 — отдельный LLM-судья. Экспертные пороги этим не подтверждаются.','',
            'Для интеграции оставлены GLM как стартовый генератор и Qwen как критик; у Qwen больше найденных внесённых ошибок. Победитель по рублёвой цене не назначен. Сырые VLM-страницы требуют сверки и не принимаются в BankInput до неё.','']
    (DOCS/"01_llm_mapping.md").write_text("\n".join(model_lines))
    prompt_lines=["# Промпты и протокол проверки", "", "Тексты в `prompts/`, полный машиночитаемый реестр — `prompts/manifest.json`. Входные и выходные JSON-схемы экспортированы в `schemas/`. Общие правила — `common_v2.txt`: три слоя, проверяемые источники, готовые числа, недоверенный внешний текст и честность о пробелах.", "", "Few-shot пока не используется: примеры золотого набора в system-текст не встроены. Поля constraints/few_shot/eval_cases/status хранятся в реестре. Статус прогона не равен экспертной приёмке.", "", "| ID | Текст и версия | Вход | Выход | Модель | Лимит выхода |", "|---|---|---|---|---|---|"]
    for pid,spec in manifest['prompts'].items():
        prompt_lines.append(f"| {pid} | [{spec['file']}](../../prompts/{spec['file']}); v{spec['version']} | [{spec['input_schema']}](../../schemas/{spec['input_schema']}.json) | [{spec['schema']}](../../schemas/{spec['schema']}.json) | {spec['model']} | {spec['max_tokens']} |")
    prompt_lines+=['','| Промпт | Случаи seed | Статус автоматической проверки |','|---|---|---|']
    for pid,spec in manifest['prompts'].items():
        prompt_lines.append(f"| {pid} | {', '.join(spec['eval_cases']) or 'не заполнено'} | {spec['status']} |")
    prompt_lines += ["", "## Воспроизведение", "", "```bash", "uv run --env-file .env --extra backend python -m pe.acceptance matrix --out out/acceptance", "uv run --env-file .env --extra backend python -m pe.acceptance cards --out out/acceptance", "```", "", "Matrix проверяет каждый PRM на трёх синтетических случаях seed команды. Для VLM передаются реальные изображения страниц корпуса. Cards сравнивает два генератора на 12 случаях с независимым критиком и ограниченным исправлением. Набор атак, внесённых ошибок, рубрика и их фактические результаты отражены в [отчёте](evaluation/acceptance_summary.md).", "", "Для A/B фиксируются seed, версия/хэш промпта, набор источников, температура и лимиты; контекст и критерии одинаковы. Изменения после анализа ошибки оформляются новой версией. Hold-out не используется для выбора промпта. Метрики на seed и синтетических атаках отделяются от экспертной проверки реальных карточек.", ""]
    (DOCS/"03_basic_prompts.md").write_text("\n".join(prompt_lines))
    print('Generated 3 required documents;',len(covered),'metric passports, 24 formulas, 7 charts')


